catalog_script_client.script:
function onSubmit() {
    //set variables
    var admin_permission = g_user.hasRole('x_hccc_hoc_ohs.admin');
    var advisor_permission = g_user.hasRole('x_hccc_hoc_ohs.advisor');

    if (admin_permission || advisor_permission) {
        return true;
    }

    var committee_permission = g_user.hasRole('x_hccc_hoc_ohs.committee');
    var report_type = g_form.getValue('ohsm_repo_report');

    if ((report_type === '2306fd9c8774ad5050d2eca73cbb3500' || report_type === '55703d708701a99450d2eca73cbb3566') && committee_permission) { //if LAB 1058
        return true;
    } else {
        g_form.addErrorMessage("Invalid permissions. You do not have the correct permissions to submit this report.");
        return false;
    }
}
